<template>
  <div class="listing-page page-enter">
    <section class="listing-intro"><div><span class="jade-eyebrow">每一种生活，都有合适的空间</span><h1>找一处，喜欢的日常。</h1><p>从通勤、预算和生活习惯出发，慢慢找到适合你的家。</p></div><form class="listing-search" @submit.prevent="applySearch"><label class="visually-hidden" for="listing-keyword">搜索房源</label><input id="listing-keyword" v-model="searchInput" type="search" placeholder="区域、商圈或小区"><button aria-label="搜索房源" type="submit"><ArrowIcon /></button></form></section>
    <section class="listing-filters" aria-label="房源筛选"><div class="filter-row"><span class="filter-label">城市</span><div class="filter-options"><button v-for="city in cities" :key="city" :class="{ on: city === selectedCity }" :aria-pressed="city === selectedCity" @click="setCity(city)">{{ city }}</button></div></div><div v-if="districts.length" class="filter-row"><span class="filter-label">区域</span><div class="filter-options"><button :class="{ on: !district }" :aria-pressed="!district" @click="district = ''">不限</button><button v-for="d in districts" :key="d" :class="{ on: district === d }" :aria-pressed="district === d" @click="district = d">{{ d }}</button></div></div><div class="filter-row"><span class="filter-label">月租</span><div class="filter-options"><button v-for="(range, i) in prices" :key="range.label" :class="{ on: priceIndex === i }" :aria-pressed="priceIndex === i" @click="priceIndex = i">{{ range.label }}</button></div></div><div class="filter-row"><span class="filter-label">户型</span><div class="filter-options"><button v-for="(label, i) in ['不限','一室','两室','三室及以上']" :key="label" :class="{ on: bedrooms === i }" :aria-pressed="bedrooms === i" @click="bedrooms = i">{{ label }}</button></div></div></section>
    <section class="listing-results"><div class="listing-toolbar"><p v-if="!loading" role="status">{{ selectedCity }}<template v-if="district"> · {{ district }}</template> <span>找到 <strong>{{ filtered.length }}</strong> 套房源</span></p><p v-else>正在寻找好房……</p><label>排序 <select v-model="sort"><option value="default">综合排序</option><option value="price_asc">租金从低到高</option><option value="price_desc">租金从高到低</option><option value="area">面积从大到小</option></select></label></div>
      <div v-if="loading" class="listing-grid" aria-busy="true" aria-label="正在加载房源"><div v-for="n in 6" :key="n" class="listing-placeholder"></div></div>
      <div v-else-if="error" class="listing-empty"><h2>房源暂时没加载出来</h2><p>请检查服务连接，稍后再试。</p><button class="jade-button" @click="load">重新加载 <ArrowIcon /></button></div>
      <div v-else-if="!filtered.length" class="listing-empty"><h2>换个条件，也许就遇见了。</h2><p>试试放宽区域、租金或户型条件，看看更多可能。</p><button class="jade-button" @click="reset">清除筛选 <ArrowIcon /></button></div>
      <div v-else class="listing-grid"><RouterLink v-for="house in visibleHouses" :key="house.id" :to="'/detail/' + house.id" class="listing-card"><div class="listing-picture"><img v-if="house.coverImage" :src="house.coverImage" :alt="house.title || '房源照片'" loading="lazy" @error="fallback"><span v-else class="no-photo">等待一张家的照片</span><span class="listing-photo-note">{{ house.district }}<template v-if="house.decoration"> · {{ house.decoration }}</template></span><span class="listing-hover">走近这个家 <ArrowIcon /></span></div><div class="listing-card-body"><h2>{{ house.title || '好房等你来了解' }}</h2><p>{{ house.bedrooms }}室{{ house.livingRooms }}厅 <span>·</span> {{ house.area }}㎡ <template v-if="house.orientation"><span>·</span> {{ house.orientation }}向</template></p><div class="listing-card-bottom"><strong>¥ {{ Number(house.price || 0).toLocaleString('zh-CN') }}<small> / 月</small></strong><ArrowIcon /></div><small v-if="house.subwayStationName" class="listing-subway">近 {{ house.subwayStationName }}站<template v-if="house.distanceToSubway"> · {{ house.distanceToSubway }}m</template></small></div></RouterLink></div>
      <nav v-if="pageCount > 1" class="listing-pagination" aria-label="房源分页"><button :disabled="page === 1" @click="turnPage(page - 1)">上一页</button><span>{{ page }} / {{ pageCount }}</span><button :disabled="page === pageCount" @click="turnPage(page + 1)">下一页 <ArrowIcon /></button></nav>
    </section><section class="listing-help"><span>还没有找到喜欢的？</span><RouterLink class="jade-link" to="/app/chat">说说需求，让小易帮你一起找 <ArrowIcon /></RouterLink></section><SiteFooter />
  </div>
</template>
<script setup>
import { ref, computed, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { cities, useCity } from '../composables/useCity'
import { houseApi } from '../api/house'
import ArrowIcon from './ArrowIcon.vue'
import SiteFooter from './SiteFooter.vue'
import { isReducedMotion } from '../composables/motionPreference'
const route = useRoute(), router = useRouter()
const {currentCity,setCurrentCity}=useCity()
const selectedCity = computed(() => cities.includes(route.query.city) ? route.query.city : currentCity.value)
const searchInput = ref(typeof route.query.keyword === 'string' ? route.query.keyword : ''), keyword = ref(searchInput.value)
const houses = ref([]), loading = ref(true), error = ref(false), district = ref(''), priceIndex = ref(0), bedrooms = ref(0), sort = ref('default'), page = ref(1)
const prices = [{ label:'不限', min:0, max:Infinity }, { label:'1500元以下', min:0, max:1500 }, { label:'1500–3000元', min:1500, max:3000 }, { label:'3000–5000元', min:3000, max:5000 }, { label:'5000元以上', min:5000, max:Infinity }]
const districts = computed(() => [...new Set(houses.value.map(h => h.district).filter(Boolean))])
const filtered = computed(() => {
  const range = prices[priceIndex.value], term = keyword.value.toLowerCase()
  let list = houses.value.filter(h => (!district.value || h.district === district.value) && Number(h.price) >= range.min && (range.max === Infinity || Number(h.price) < range.max) && (!bedrooms.value || (bedrooms.value === 3 ? Number(h.bedrooms) >= 3 : Number(h.bedrooms) === bedrooms.value)) && (!term || [h.title,h.district,h.address,h.subwayStationName].some(v => String(v || '').toLowerCase().includes(term))))
  if (sort.value === 'price_asc') list.sort((a,b) => a.price-b.price)
  if (sort.value === 'price_desc') list.sort((a,b) => b.price-a.price)
  if (sort.value === 'area') list.sort((a,b) => b.area-a.area)
  return list
})
const pageCount = computed(() => Math.max(1, Math.ceil(filtered.value.length / 12)))
const visibleHouses = computed(() => filtered.value.slice((page.value - 1) * 12, page.value * 12))
let requestVersion = 0
async function load() { const version = ++requestVersion; loading.value = true; error.value = false; try { const r = await houseApi.list({ city:selectedCity.value, status:'APPROVED', sortBy:'price_asc', page:1, size:5000 }); if (version !== requestVersion) return; houses.value = Array.isArray(r.data) ? r.data : r.data?.list || r.data?.records || [] } catch { if(version === requestVersion) error.value = true } finally { if(version === requestVersion) loading.value = false } }
function setCity(city) { setCurrentCity(city); router.replace({ query:{ ...route.query, city } }) }
function applySearch() { keyword.value = searchInput.value.trim(); router.replace({ query:{ ...route.query, city:selectedCity.value, keyword:keyword.value || undefined } }) }
function reset(){ district.value = ''; priceIndex.value = 0; bedrooms.value = 0; searchInput.value = ''; applySearch() }
function turnPage(value){ page.value = value; document.querySelector('.listing-toolbar')?.scrollIntoView({ behavior:isReducedMotion() ? 'instant' : 'smooth' }) }
function fallback(event){ const img='/house-images/uns_1600210492486-724fe5c67fb0.jpg'; if(!event.target.src.endsWith(img)) event.target.src=img }
watch(selectedCity, () => { setCurrentCity(selectedCity.value); district.value=''; page.value=1; load() }, { immediate:true })
watch(() => route.query.keyword, value => { keyword.value = typeof value === 'string' ? value : ''; searchInput.value = keyword.value })
watch([district,priceIndex,bedrooms,keyword,sort], () => { page.value=1 })
</script>
