-size:10px;color:var(--jade-muted);padding-top:13px}.listing-empty{padding:70px 20px;text-align:center;background:#fff;border:1px solid var(--jade-line)}.listing-empty h2{font-family:var(--font-display);font-size:27px;font-weight:500}.listing-empty p{font-size:13px;color:var(--jade-muted);margin:12px 0 25px}.listing-placeholder{aspect-ratio:1.1;background:#e7e8df;animation:listingPulse 1.5s infinite;border-radius:4px}.listing-pagination{display:flex;justify-content:center;align-items:center;gap:25px;padding-top:40px}.listing-pagination button{display:flex;align-items:center;gap:15px;border:1px solid var(--jade-line);padding:10px 17px;font-size:12px;background:white;color:var(--jade-900);border-radius:3px}.listing-pagination button svg{width:17px;height:17px}.listing-pagination button:disabled{opacity:.4}.listing-pagination>span{font-size:12px;color:var(--jade-muted)}.listing-help{padding:20px var(--page-gutter) 55px;text-align:center;font-size:13px;display:flex;align-items:center;justify-content:center;gap:24px;color:var(--jade-muted)}.listing-help .jade-link{font-size:13px}.no-photo{position:absolute;inset:0;display:grid;place-items:center;color:var(--jade-muted)}.visually-hidden{position:absolute;width:1px;height:1px;clip:rect(0 0 0 0);overflow:hidden}@keyframes listingPulse{50%{opacity:.5}}@keyframes listingIn{from{opacity:.5;transform:translateY(8px)}to{opacity:1;transform:none}}
@media(max-width:1000px){.listing-intro{align-items:flex-start;flex-direction:column;gap:25px}.listing-search{width:100%}.listing-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.listing-intro h1{font-size:32px}}
@media(max-width:600px){.listing-intro{padding-top:30px}.listing-intro h1{font-size:28px}.listing-intro p{font-size:11px;line-height:1.9}.listing-search{min-width:0}.listing-filters{padding:6px 15px}.filter-row{gap:8px;padding:10px 0}.filter-options{gap:4px}.filter-options button{font-size:11px;padding:4px 7px}.filter-label{font-size:11px;width:28px}.filter-row:first-child .filter-options{max-height:82px;overflow:auto}.listing-toolbar{font-size:12px;align-items:flex-start}.listing-toolbar p>span{display:block;margin:5px 0 0;font-size:11px}.listing-toolbar select{max-width:125px;font-size:11px}.listing-grid{gap:18px 12px}.listing-picture{aspect-ratio:1.2}.listing-card-body{padding:12px}.listing-card-body h2{font-size:12px}.listing-card-body p{font-size:10px;gap:4px;flex-wrap:wrap;margin:8px 0 12px}.listing-card-bottom strong{font-size:17px}.listing-card-bottom>svg{display:none}.listing-photo-note{left:7px;top:7px;font-size:9px;padding:4px}.listing-subway{font-size:9px}.listing-help{flex-direction:column;gap:12px}.listing-empty h2{font-size:23px}.listing-pagination{gap:15px}}
